/**
 * Prints the i18next file the Sonos developer portal takes (served at /sonos/i18n.json) for this
 * checkout, so it can be uploaded without deploying the build first:
 *
 *     npm run --silent i18n-json > i18n.json
 *
 * Run it with the Node version bonob builds with (node:20 in the Dockerfile); node_modules' native
 * modules fail to load under another version. `--silent` keeps npm's own banner out of the file.
 *
 * The file is generated by the server's own route, so it is exactly what the build serves.
 * BNB_SONOS_SERVICE_NAME is substituted as the deployed integrations use it ("Astiga").
 */
import request from "supertest";
import makeServer from "../src/server";
import { SONOS_DISABLED } from "../src/sonos";
import { MusicService } from "../src/music_service";
import { PersistentTokenStore } from "../src/api_tokens";
import url from "../src/url_builder";
import { I18N_ROUTE } from "../src/smapi";

const SERVICE_NAME = "Astiga";

const server = makeServer(
  SONOS_DISABLED,
  { name: SERVICE_NAME, sid: 0, uri: "", secureUri: "", authType: "AppLink" },
  url("http://localhost:4534"),
  {} as MusicService,
  {},
  {} as PersistentTokenStore
);

request(server)
  .get(I18N_ROUTE)
  .then((res) => {
    if (res.status !== 200) {
      process.stderr.write(`${I18N_ROUTE} answered ${res.status}\n`);
      process.exit(1);
    }
    process.stdout.write(JSON.stringify(res.body, null, 2) + "\n");
    process.exit(0);
  });
